begin;
do $$
declare c public.deal_financial_closures%rowtype; original_gross numeric; count_before bigint; count_after bigint; current_closure uuid; got boolean; saved_status text; actor uuid; cfg jsonb;
begin
 select * into c from public.deal_financial_closures where status='posted' order by closed_at desc limit 1;
 if c.id is null then raise exception 'Fixture: at least one posted closure is required'; end if;
 select count(*) into count_before from public.payouts;
 perform helix_private.post_deal_finances(c.deal_id);
 perform helix_private.post_deal_finances(c.deal_id);
 select count(*) into count_after from public.payouts;
 if count_before<>count_after then raise exception 'Repeated completion duplicated payouts'; end if;
 if exists(select 1 from public.deal_financial_closures f where f.status='posted' and f.retained<>(f.agency_net-coalesce((select amount from public.agency_financial_adjustments a where a.closure_id=f.id),0)+(select coalesce(sum(amount),0) from public.payouts p where p.closure_id=f.id))) then raise exception 'Financial entries do not conserve retained commission'; end if;
 got:=false;
 begin update public.deals set amount=amount+1 where id=c.deal_id;
 exception when others then if SQLERRM like 'Reabra o negócio%' then got:=true;else raise;end if; end;
 if not got then raise exception 'Closed deal financial inputs were mutable'; end if;
 select status into saved_status from public.payouts where closure_id=c.id and role='pensao' limit 1;
 update public.payouts set status='pago' where closure_id=c.id and role='pensao';
 got:=false;
 begin update public.deals set stage='escritura' where id=c.deal_id;
 exception when others then if SQLERRM like 'O fecho tem pagamentos%' then got:=true;else raise;end if; end;
 if not got then raise exception 'Paid closure could be silently reversed'; end if;
 update public.payouts set status=saved_status where closure_id=c.id and role='pensao';
 select id into actor from public.profiles where id=(c.snapshot->'financials'->'producers'->0->>'id')::uuid;
 select monthly_gross into original_gross from public.profiles where id=actor;
 update public.deals set stage='escritura' where id=c.deal_id;
 if not exists(select 1 from public.deal_financial_closures where id=c.id and status='reversed') or exists(select 1 from public.payouts where closure_id=c.id and status<>'anulado') then raise exception 'Reopening failed to reverse all accounting entries'; end if;
 update public.deals set stage='concluido' where id=c.deal_id;
 select id into current_closure from public.deal_financial_closures where deal_id=c.deal_id and status='posted';
 if current_closure is null or current_closure=c.id or (select count(*) from public.deal_financial_closures where deal_id=c.deal_id and status='posted')<>1 then raise exception 'Reclosing did not create exactly one active revision'; end if;
 if (select monthly_gross from public.profiles where id=actor)<>original_gross then raise exception 'Reopening/reclosing doubled turnover'; end if;
 if not exists(select 1 from public.deal_financial_closures where id=current_closure and pension_total=c.pension_total and royalties_agent=c.royalties_agent and royalties_agency=c.royalties_agency) then raise exception 'Reclosing changed the same historical calculation'; end if;
 perform set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',actor)::text,true);
 got:=false;
 begin update public.payouts set closure_id=null where closure_id=current_closure and role='pensao';
 exception when others then if SQLERRM like 'Os valores de um fecho%' then got:=true;else raise;end if; end;
 if not got then raise exception 'A client detached a payout from its financial closure'; end if;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 select id into actor from public.profiles where active and role_key='superadmin' order by created_at limit 1;
 perform public.set_email_delivery_config('teste@example.invalid','',true,actor,'re_fake_transaction_test_only');
 cfg:=public.get_email_delivery_config();
 if cfg ? 'apiKey' or cfg ? 'secret_id' or not (cfg->>'keyConfigured')::boolean then raise exception 'Email settings exposed the credential or did not save it'; end if;
 cfg:=public.get_email_delivery_credentials();
 if cfg->>'apiKey'<>'re_fake_transaction_test_only' then raise exception 'Encrypted credential roundtrip failed'; end if;
 if has_function_privilege('anon','public.get_email_delivery_credentials()','EXECUTE') or has_function_privilege('authenticated','public.get_email_delivery_credentials()','EXECUTE') then raise exception 'A public role can retrieve email credentials'; end if;
 if has_table_privilege('anon','public.deal_financial_closures','SELECT') or has_table_privilege('authenticated','public.deal_financial_closures','SELECT') then raise exception 'Closure snapshots are publicly readable'; end if;
end $$;
rollback;
select 'Verified: exact-once accrual, conserved cents, immutable snapshot, reversal/reclose, paid guard, encrypted credentials, private grants. All test writes rolled back.' as verified;
